wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::types::{AgentResponse, Intent, LlmError};
use crate::aap::caps::{kb_read, tool_llm};

const SYSTEM: &str = "You answer customer-support questions. \
Answer from the question and the provided knowledge. \
Use the lookup tool only when the knowledge is insufficient.";

/// Bound on model/tool round trips, so a looping model cannot run forever.
const MAX_ROUNDS: usize = 3;
/// Bound on the query string the model may send to the knowledge base.
const MAX_LOOKUP_QUERY: usize = 512;

struct Node;

fn intent_label(i: Intent) -> &'static str {
    match i {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push_str("\nQuestion: ");
    p.push_str(&ctx.question);
    if !ctx.knowledge.is_empty() {
        p.push_str("\nKnowledge:");
        for k in &ctx.knowledge {
            p.push_str("\n- ");
            p.push_str(k);
        }
    }
    p
}

fn answer(ctx: &ConversationContext) -> Result<String, String> {
    let mut prompt = build_prompt(ctx);

    for _ in 0..MAX_ROUNDS {
        match tool_llm::generate(SYSTEM, &prompt) {
            tool_llm::Reply::Text(text) => return Ok(text),
            tool_llm::Reply::Call(req) => {
                // Only the `lookup` tool is in this node's scope.
                if req.tool != "lookup" {
                    return Err(format!("tool '{}' is not in scope", req.tool));
                }
                if req.query.len() > MAX_LOOKUP_QUERY {
                    return Err("lookup query exceeds bound".to_string());
                }
                let hits = kb_read::lookup(&req.query);
                prompt.push_str("\nLookup ");
                prompt.push_str(&req.query);
                prompt.push_str(" =>");
                for h in &hits {
                    prompt.push_str("\n- ");
                    prompt.push_str(h);
                }
            }
        }
    }

    Err("tool-call round limit reached".to_string())
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        match answer(&ctx) {
            Ok(text) => ResponseResult::Ok(AgentResponse { text }),
            Err(message) => ResponseResult::Error(LlmError { message }),
        }
    }
}

export!(Node);
```

